-- Preparation staging only; NOT production migrations. PostgreSQL execution NOT VERIFIED.
BEGIN;
DO $$ BEGIN IF current_database() <> 'logistics_prep_test' THEN RAISE EXCEPTION 'Preparation import requires isolated logistics_prep_test database'; END IF; END $$;
CREATE SCHEMA IF NOT EXISTS competition_preparation;
SET LOCAL search_path=competition_preparation;
CREATE TABLE IF NOT EXISTS entities (
 id UUID PRIMARY KEY, scenario TEXT NOT NULL, kind TEXT NOT NULL, code TEXT NOT NULL,
 source TEXT NOT NULL CHECK(source='synthetic'), payload JSONB NOT NULL,
 UNIQUE(scenario,kind,code));
CREATE TABLE IF NOT EXISTS refs (
 source_id UUID NOT NULL REFERENCES entities(id), relation TEXT NOT NULL,
 target_id UUID NOT NULL REFERENCES entities(id),
 PRIMARY KEY(source_id,relation,target_id));
COMMIT;
